[CmdletBinding()]
param(
    [switch]$AuditOnly
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'

# ===========================
# Настройки
# ===========================
$Config = @{
    # Прямые официальные ссылки на сертификаты. Чтобы добавить или заменить
    # сертификат, измените только этот список. Тип хранилища определяется
    # автоматически по содержимому сертификата.
    CertificateUrls = @(
        'https://gu-st.ru/content/downloads/Russian_Trusted_Root_CA.cer'
        'https://gu-st.ru/content/downloads/Russian_Trusted_Sub_CA.cer'
        'https://gu-st.ru/content/downloads/Russian_Trusted_Sub_CA_2024.cer'
    )

    # В этой папке хранятся скачанные сертификаты и журнал.
    UpdateDirectory = 'C:\update'

    # Пауза после каждой строки консоли. Нужна, чтобы Run Commands в MeshCentral
    # не терял быстрые последовательности stdout. 0 отключает задержку.
    # Рекомендуется: 100. При обрезании вывода попробуйте 200-250.
    ConsoleLineDelayMilliseconds = 100

    # Пауза перед exit, чтобы агент MC успел передать последний блок stdout.
    # 0 отключает задержку. Рекомендуется: 1000. При обрезании конца вывода
    # увеличьте до 2000-3000. Значение указано в миллисекундах.
    FinalExitDelayMilliseconds = 1000
}

# Коды завершения, возвращаемые в MeshCentral.
$ExitCodes = @{
    Success       = 0
    Prerequisites = 10
    Download      = 20
    Validation    = 40
    Installation  = 50
    Unexpected    = 99
}

$auditModeText = if ($AuditOnly.IsPresent) { 'Да' } else { 'Нет' }

$updateDirectory = $Config.UpdateDirectory
$logDirectory = Join-Path $updateDirectory 'RussianTrustedCA'
$logFile = Join-Path $logDirectory 'install.log'
$runsDirectory = Join-Path $logDirectory 'runs'
$runName = '{0}-{1}-{2}' -f (Get-Date -Format 'yyyyMMdd-HHmmss'), $PID, [Guid]::NewGuid().ToString('N')
$workDirectory = Join-Path $runsDirectory $runName
$script:LogTextEncoding = [System.Text.Encoding]::Unicode

function Initialize-InstallLog {
    if (-not (Test-Path -LiteralPath $logDirectory)) {
        New-Item -ItemType Directory -Path $logDirectory -Force | Out-Null
    }

    $legacyLogPath = $null
    if (Test-Path -LiteralPath $logFile) {
        $existingLog = Get-Item -LiteralPath $logFile
        if ($existingLog.Length -gt 0) {
            $stream = New-Object System.IO.FileStream($logFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            try {
                $firstByte = $stream.ReadByte()
                $secondByte = $stream.ReadByte()
            }
            finally {
                $stream.Close()
            }

            $isUnicodeLog = ($firstByte -eq 0xFF) -and ($secondByte -eq 0xFE)
            if (-not $isUnicodeLog) {
                $legacyName = 'install-legacy-{0}-{1}.log' -f (Get-Date -Format 'yyyyMMdd-HHmmss'), [Guid]::NewGuid().ToString('N').Substring(0, 8)
                $legacyLogPath = Join-Path $logDirectory $legacyName
                Move-Item -LiteralPath $logFile -Destination $legacyLogPath
            }
        }
    }

    if (-not (Test-Path -LiteralPath $logFile)) {
        [System.IO.File]::WriteAllText($logFile, '', $script:LogTextEncoding)
    }

    return $legacyLogPath
}

function Write-InstallLog {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Message,

        [ValidateSet('INFO', 'WARN', 'ERROR')]
        [string]$Level = 'INFO'
    )

    $line = '{0} [{1}] {2}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Level, $Message
    Write-Host $line

    try {
        [Console]::Out.Flush()
    }
    catch {
        # В некоторых средах PowerShell прямой доступ к Console.Out недоступен.
    }

    try {
        if (-not (Test-Path -LiteralPath $logFile)) {
            Initialize-InstallLog | Out-Null
        }

        $stream = New-Object System.IO.FileStream($logFile, [System.IO.FileMode]::Append, [System.IO.FileAccess]::Write, [System.IO.FileShare]::Read)
        $writer = New-Object System.IO.StreamWriter($stream, $script:LogTextEncoding)
        try {
            $writer.WriteLine($line)
        }
        finally {
            $writer.Close()
            $stream.Close()
        }
    }
    catch {
        Write-Warning ('Не удалось записать журнал {0}: {1}' -f $logFile, $_.Exception.Message)
    }

    if ($Config.ConsoleLineDelayMilliseconds -gt 0) {
        Start-Sleep -Milliseconds $Config.ConsoleLineDelayMilliseconds
    }
}

function Test-IsAdministrator {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($identity)
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

function Invoke-OfficialDownload {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Uri,

        [Parameter(Mandatory = $true)]
        [string]$Destination
    )

    $errors = New-Object System.Collections.Generic.List[string]

    try {
        Write-InstallLog ('Скачивание через PowerShell: {0}' -f $Uri)
        Invoke-WebRequest -UseBasicParsing -Uri $Uri -OutFile $Destination -TimeoutSec 120
        if ((Get-Item -LiteralPath $Destination).Length -le 0) {
            throw 'Скачанный файл пуст.'
        }
        return
    }
    catch {
        $errors.Add(('Invoke-WebRequest: {0}' -f $_.Exception.Message))
        Remove-Item -LiteralPath $Destination -Force -ErrorAction SilentlyContinue
    }

    $curl = Get-Command 'curl.exe' -ErrorAction SilentlyContinue
    if ($null -ne $curl) {
        try {
            Write-InstallLog ('Скачивание через PowerShell не удалось; повторная попытка через curl.exe: {0}' -f $Uri) 'WARN'
            & $curl.Source --fail --location --silent --show-error --connect-timeout 30 --max-time 120 --output $Destination $Uri
            if ($LASTEXITCODE -ne 0) {
                throw ('curl.exe завершился с кодом {0}.' -f $LASTEXITCODE)
            }
            if ((Get-Item -LiteralPath $Destination).Length -le 0) {
                throw 'Скачанный файл пуст.'
            }
            return
        }
        catch {
            $errors.Add(('curl.exe: {0}' -f $_.Exception.Message))
            Remove-Item -LiteralPath $Destination -Force -ErrorAction SilentlyContinue
        }
    }
    else {
        $errors.Add('curl.exe: отсутствует в этой версии Windows.')
    }

    try {
        Write-InstallLog ('Предыдущие способы скачивания не сработали; повторная попытка через WebClient: {0}' -f $Uri) 'WARN'
        $webClient = New-Object System.Net.WebClient
        try {
            $webClient.DownloadFile($Uri, $Destination)
        }
        finally {
            $webClient.Dispose()
        }
        if ((Get-Item -LiteralPath $Destination).Length -le 0) {
            throw 'Скачанный файл пуст.'
        }
        return
    }
    catch {
        $errors.Add(('WebClient: {0}' -f $_.Exception.Message))
        Remove-Item -LiteralPath $Destination -Force -ErrorAction SilentlyContinue
    }

    throw ('Не удалось скачать {0} ни одним способом. {1}' -f $Uri, ($errors -join ' | '))
}

function Get-CertificateInfo {
    param(
        [Parameter(Mandatory = $true)]
        [System.IO.FileInfo]$File
    )

    $certificate = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2($File.FullName)
    $basicConstraints = $certificate.Extensions | Where-Object { $_.Oid.Value -eq '2.5.29.19' } | Select-Object -First 1
    if ($null -eq $basicConstraints) {
        throw ('Файл не является сертификатом центра сертификации (нет Basic Constraints): {0}' -f $File.Name)
    }

    $decodedConstraints = New-Object System.Security.Cryptography.X509Certificates.X509BasicConstraintsExtension
    $decodedConstraints.CopyFrom($basicConstraints)
    if (-not $decodedConstraints.CertificateAuthority) {
        throw ('Файл не помечен как сертификат центра сертификации: {0}' -f $File.Name)
    }

    if ($certificate.HasPrivateKey) {
        throw ('Сертификат неожиданно содержит закрытый ключ: {0}' -f $File.Name)
    }

    $subjectRaw = [Convert]::ToBase64String($certificate.SubjectName.RawData)
    $issuerRaw = [Convert]::ToBase64String($certificate.IssuerName.RawData)
    $isSelfSigned = $subjectRaw -eq $issuerRaw
    $storeName = if ($isSelfSigned) { 'Root' } else { 'CA' }

    return [pscustomobject]@{
        File        = $File
        Certificate = $certificate
        StoreName   = $StoreName
    }
}

function Install-CertificateFile {
    param(
        [Parameter(Mandatory = $true)]
        [psobject]$CertificateInfo
    )

    $certificate = $CertificateInfo.Certificate
    $certificateFileName = $CertificateInfo.File.Name
    $storeName = $CertificateInfo.StoreName
    $storePath = 'Cert:\LocalMachine\{0}' -f $storeName
    $existing = Get-ChildItem -Path $storePath | Where-Object { $_.Thumbprint -eq $certificate.Thumbprint } | Select-Object -First 1

    if ($null -ne $existing) {
        Write-InstallLog ('Уже установлен: файл={0}; отпечаток={1}; хранилище={2}' -f $certificateFileName, $certificate.Thumbprint, $storePath)
        return 'AlreadyInstalled'
    }

    if ($certificate.NotAfter -lt (Get-Date)) {
        Write-InstallLog ('Просроченный сертификат пропущен: файл={0}; истёк={1:yyyy-MM-dd}; отпечаток={2}' -f $certificateFileName, $certificate.NotAfter, $certificate.Thumbprint) 'WARN'
        return 'Expired'
    }

    if ($AuditOnly) {
        Write-InstallLog ('АУДИТ: будет установлен: файл={0}; действуетДо={1:yyyy-MM-dd}; отпечаток={2}; хранилище={3}' -f $certificateFileName, $certificate.NotAfter, $certificate.Thumbprint, $storePath)
        return 'Audit'
    }

    Write-InstallLog ('Установка: файл={0}; действуетДо={1:yyyy-MM-dd}; отпечаток={2}; хранилище={3}' -f $certificateFileName, $certificate.NotAfter, $certificate.Thumbprint, $storePath)
    $certutilOutput = & certutil.exe -addstore -f $storeName $CertificateInfo.File.FullName 2>&1
    if ($LASTEXITCODE -ne 0) {
        throw ('certutil.exe не смог установить {0}; код={1}; вывод: {2}' -f $CertificateInfo.File.Name, $LASTEXITCODE, ($certutilOutput -join ' '))
    }

    $installed = Get-ChildItem -Path $storePath | Where-Object { $_.Thumbprint -eq $certificate.Thumbprint } | Select-Object -First 1
    if ($null -eq $installed) {
        throw ('После завершения certutil.exe сертификат не найден в {0}: {1}' -f $storePath, $certificate.Thumbprint)
    }

    Write-InstallLog ('Успешно установлен: {0}' -f $certificate.Thumbprint)
    return 'Installed'
}

$exitCode = $ExitCodes.Unexpected
$currentStage = 'Запуск'

try {
    $legacyLogPath = Initialize-InstallLog
    if (-not [string]::IsNullOrEmpty($legacyLogPath)) {
        Write-InstallLog ('Предыдущий журнал имел другую кодировку и сохранён как: {0}' -f $legacyLogPath) 'WARN'
    }

    $currentIdentity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $currentSid = if ($null -ne $currentIdentity.User) { $currentIdentity.User.Value } else { 'неизвестен' }
    $runContext = if ($currentSid -eq 'S-1-5-18') { 'LocalSystem' } else { 'Пользователь' }
    Write-InstallLog ('Запуск установки российских доверенных сертификатов. Компьютер={0}; Контекст={1}; SID={2}; ТолькоАудит={3}' -f $env:COMPUTERNAME, $runContext, $currentSid, $auditModeText)

    $currentStage = 'Проверка требований'
    $exitCode = $ExitCodes.Prerequisites
    if (-not $AuditOnly -and -not (Test-IsAdministrator)) {
        throw 'Требуются права администратора или LocalSystem. Запустите скрипт через MeshCentral от имени агента/службы.'
    }

    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    }
    catch {
        Write-InstallLog ('Не удалось явно включить TLS 1.2: {0}' -f $_.Exception.Message) 'WARN'
    }

    New-Item -ItemType Directory -Path $workDirectory -Force | Out-Null

    $certificatesDirectory = Join-Path $workDirectory 'certificates'
    New-Item -ItemType Directory -Path $certificatesDirectory -Force | Out-Null
    $certificateInfos = New-Object System.Collections.Generic.List[object]
    $duplicateCount = 0

    foreach ($certificateUrl in $Config.CertificateUrls) {
        $uri = New-Object System.Uri($certificateUrl)
        $certificateFileName = [System.IO.Path]::GetFileName($uri.AbsolutePath)
        if ([string]::IsNullOrEmpty($certificateFileName)) {
            throw ('Не удалось определить имя файла из URL: {0}' -f $certificateUrl)
        }

        $certificatePath = Join-Path $certificatesDirectory $certificateFileName
        $currentStage = 'Скачивание сертификата {0}' -f $certificateFileName
        $exitCode = $ExitCodes.Download
        Invoke-OfficialDownload -Uri $certificateUrl -Destination $certificatePath
        $certificateFile = Get-Item -LiteralPath $certificatePath
        Write-InstallLog ('Скачано {0} байт: {1}' -f $certificateFile.Length, $certificateUrl)

        $currentStage = 'Проверка сертификата {0}' -f $certificateFile.Name
        $exitCode = $ExitCodes.Validation
        $certificateInfo = Get-CertificateInfo -File $certificateFile
        $duplicate = $certificateInfos | Where-Object { $_.Certificate.Thumbprint -eq $certificateInfo.Certificate.Thumbprint } | Select-Object -First 1
        if ($null -ne $duplicate) {
            $duplicateCount++
            Write-InstallLog ('Дубликат пропущен: файл={0}; отпечаток={1}' -f $certificateFile.Name, $certificateInfo.Certificate.Thumbprint)
        }
        else {
            $certificateInfos.Add($certificateInfo)
            Write-InstallLog ('Сертификат проверен: файл={0}; хранилище={1}; отпечаток={2}' -f $certificateFile.Name, $certificateInfo.StoreName, $certificateInfo.Certificate.Thumbprint)
        }
    }

    $installedCount = 0
    $existingCount = 0
    $expiredCount = 0
    $auditCount = 0

    foreach ($certificateInfo in $certificateInfos) {
        $currentStage = 'Установка сертификата {0}' -f $certificateInfo.File.Name
        $exitCode = $ExitCodes.Installation
        $result = Install-CertificateFile -CertificateInfo $certificateInfo
        switch ($result) {
            'Installed'        { $installedCount++ }
            'AlreadyInstalled' { $existingCount++ }
            'Expired'          { $expiredCount++ }
            'Audit'            { $auditCount++ }
        }
    }

    $currentStage = 'Завершено'
    $exitCode = $ExitCodes.Success
    Write-InstallLog ('Успешно завершено. ExitCode={0}; Этап={1}; Найдено={2}; ДубликатовПропущено={3}; Установлено={4}; УжеУстановлено={5}; ПросроченоПропущено={6}; БудетУстановлено={7}; ТолькоАудит={8}; Файлы={9}' -f $exitCode, $currentStage, $certificateInfos.Count, $duplicateCount, $installedCount, $existingCount, $expiredCount, $auditCount, $auditModeText, $workDirectory)
}
catch {
    Write-InstallLog ('Ошибка выполнения. ExitCode={0}; Этап={1}; Ошибка={2}' -f $exitCode, $currentStage, $_.Exception.Message) 'ERROR'
}

try {
    [Console]::Out.Flush()
    [Console]::Error.Flush()
}
catch {
    # В некоторых средах PowerShell прямой доступ к Console недоступен.
}

if ($Config.FinalExitDelayMilliseconds -gt 0) {
    Start-Sleep -Milliseconds $Config.FinalExitDelayMilliseconds
}

exit $exitCode

#Requires -Version 5.1

[CmdletBinding()]
param(
    [string]$ComPort,
    [string]$HandlePath
)

$ErrorActionPreference = 'Stop'
$stopTimeout = [TimeSpan]::FromSeconds(30)
$startTimeout = [TimeSpan]::FromSeconds(30)
$hadErrors = $false
$lastPortError = $null

function ConvertFrom-ComHandleOutput {
    param([string[]]$Lines, [string]$DeviceName)

    $processName = $null
    $processId = $null
    foreach ($line in $Lines) {
        if ($line -match '^(.+?)\s+pid:\s*(\d+)\b') {
            $processName = $Matches[1].Trim()
            $processId = [int]$Matches[2]
        }
        # Handle searches by substring; require an exact device name to exclude Serial10 for Serial1.
        if ($null -ne $processId -and $line -match ('(?i)\s' + [regex]::Escape($DeviceName) + '\s*$')) {
            [pscustomobject]@{ ProcessName = $processName; ProcessId = $processId }
        }
    }
}

function Get-ComPortOwner {
    param([string]$PortName, [string]$ToolPath)

    try {
        if (-not $ToolPath) {
            foreach ($name in @('handle64.exe', 'handle.exe', 'handle64a.exe')) {
                $localPath = Join-Path $PSScriptRoot $name
                if (Test-Path -LiteralPath $localPath -PathType Leaf) { $ToolPath = $localPath; break }
                $command = Get-Command $name -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
                if ($command) { $ToolPath = $command.Source; break }
            }
        }
        if (-not $ToolPath -or -not (Test-Path -LiteralPath $ToolPath -PathType Leaf)) {
            throw 'Handle не найден. Поместите утилиту Microsoft Sysinternals Handle рядом со скриптом или укажите -HandlePath.'
        }
        # Do not open a license dialog during an unattended service restart.
        $eula = Get-ItemProperty -LiteralPath 'HKCU:\Software\Sysinternals\Handle' -Name EulaAccepted -ErrorAction SilentlyContinue
        if (-not $eula -or $eula.EulaAccepted -ne 1) {
            throw 'Сначала вручную запустите Handle под этой учётной записью и примите его лицензию.'
        }
        $serialMap = Get-Item -LiteralPath 'HKLM:\HARDWARE\DEVICEMAP\SERIALCOMM'
        $devices = @($serialMap.GetValueNames() | Where-Object { $serialMap.GetValue($_) -eq $PortName })
        if ($devices.Count -eq 0) { throw "Не найдено системное имя устройства для $PortName." }
        $owners = @(
            foreach ($device in $devices) {
                $output = @(& $ToolPath -a $device 2>&1 | ForEach-Object { "$_" })
                ConvertFrom-ComHandleOutput -Lines $output -DeviceName $device
            }
        ) | Sort-Object ProcessId -Unique
        if (-not $owners) { throw 'Handle не обнаружил процесс с открытым дескриптором порта. Это не доказывает, что порт свободен.' }
        return [pscustomobject]@{ Owners = @($owners); Note = $null }
    }
    catch {
        return [pscustomobject]@{ Owners = @(); Note = $_.Exception.Message }
    }
}

function Write-ComPortSummary {
    if (-not $ComPort) { return }
    Write-Host
    Write-Host ("===== ИТОГ ДИАГНОСТИКИ {0} =====" -f $ComPort) -ForegroundColor Cyan
    if ($ownerResult.Owners.Count -gt 0) {
        foreach ($owner in $ownerResult.Owners) {
            Write-Host ("До остановки служб порт был открыт процессом: {0}, PID {1}" -f $owner.ProcessName, $owner.ProcessId) -ForegroundColor Green
        }
    }
    else {
        Write-Host ("Процесс-владелец не установлен: {0}" -f $ownerResult.Note)
    }
    Write-Host ("Первичная проверка: {0}" -f $initialPortStatus)
    if ($releasedBy) {
        Write-Host ("Порт стал доступен после остановки службы: {0}" -f $releasedBy)
        Write-Host 'Это косвенный признак: могли также остановиться зависимые службы.'
    }
    elseif ($portInitiallyBusy) {
        Write-Host $releaseStatus
    }
    Write-Host '===================================='
}

function Get-EsmServices {
    param([Parameter(Mandatory)][string]$Pattern)

    @(Get-Service -Name $Pattern -ErrorAction SilentlyContinue | Sort-Object Name)
}

function Test-ComPortAvailable {
    param([Parameter(Mandatory)][string]$PortName)

    $serialPort = $null
    $script:lastPortError = $null
    try {
        $serialPort = [System.IO.Ports.SerialPort]::new(
            $PortName,
            9600,
            [System.IO.Ports.Parity]::None,
            8,
            [System.IO.Ports.StopBits]::One
        )
        $serialPort.Handshake = [System.IO.Ports.Handshake]::None
        $serialPort.DtrEnable = $false
        $serialPort.RtsEnable = $false
        $serialPort.Open()
        return $true
    }
    catch {
        $script:lastPortError = $_.Exception.Message
        return $false
    }
    finally {
        if ($null -ne $serialPort) {
            if ($serialPort.IsOpen) {
                $serialPort.Close()
            }
            $serialPort.Dispose()
        }
    }
}

function Stop-EsmService {
    param([Parameter(Mandatory)][System.ServiceProcess.ServiceController]$Service)

    try {
        $Service.Refresh()
        if ($Service.Status -eq [System.ServiceProcess.ServiceControllerStatus]::Stopped) {
            Write-Host ("{0} - уже остановлена." -f $Service.Name)
            return
        }

        Write-Host ("Остановка {0}..." -f $Service.Name)
        Stop-Service -InputObject $Service -Force -WarningAction SilentlyContinue -ErrorAction Stop
        $Service.WaitForStatus([System.ServiceProcess.ServiceControllerStatus]::Stopped, $stopTimeout)
        Write-Host ("{0} - остановлена." -f $Service.Name)
    }
    catch {
        $script:hadErrors = $true
        Write-Warning ("{0} - не удалось остановить: {1}" -f $Service.Name, $_.Exception.Message)
    }
}

function Start-EsmService {
    param([Parameter(Mandatory)][System.ServiceProcess.ServiceController]$Service)

    try {
        $Service.Refresh()
        if ($Service.Status -eq [System.ServiceProcess.ServiceControllerStatus]::Running) {
            Write-Host ("{0} - уже запущена." -f $Service.Name)
            return
        }

        Write-Host ("Запуск {0} (ожидание не более 30 секунд)..." -f $Service.Name)

        # Некоторые службы зависают внутри Start-Service и не возвращают управление.
        # Отдельное задание позволяет гарантированно продолжить работу по тайм-ауту.
        $startJob = Start-Job -ScriptBlock {
            param($ServiceName)
            Start-Service -Name $ServiceName -ErrorAction Stop
        } -ArgumentList $Service.Name

        if (-not (Wait-Job -Job $startJob -Timeout 30)) {
            Stop-Job -Job $startJob -ErrorAction SilentlyContinue
            Remove-Job -Job $startJob -Force -ErrorAction SilentlyContinue
            throw "Команда запуска не завершилась за 30 секунд."
        }

        try {
            Receive-Job -Job $startJob -ErrorAction Stop | Out-Null
        }
        finally {
            Remove-Job -Job $startJob -Force -ErrorAction SilentlyContinue
        }

        $Service.WaitForStatus([System.ServiceProcess.ServiceControllerStatus]::Running, $startTimeout)
        Write-Host ("{0} - запущена." -f $Service.Name)
    }
    catch {
        $script:hadErrors = $true
        Write-Warning ("{0} - не удалось запустить: {1}" -f $Service.Name, $_.Exception.Message)
    }
}

$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
$principal = [Security.Principal.WindowsPrincipal]::new($identity)
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Write-Error 'Скрипт необходимо запустить от имени администратора.'
    exit 1
}

if (-not [string]::IsNullOrWhiteSpace($ComPort)) {
    $ComPort = $ComPort.Trim().ToUpperInvariant()
    if ($ComPort -match '^\d+$') {
