function Get-InstallerFromWorkingDirectory {
    param(
        [Parameter(Mandatory = $true)]
        [string]$WorkingDirectory,

        [Parameter(Mandatory = $true)]
        [string]$Mask
    )

    Write-Log -Level "INFO" -Message "Определение рабочей директории"
    Write-Log -Level "OK" -Message ("Рабочая директория: {0}" -f $WorkingDirectory)

    Write-Log -Level "INFO" -Message "Поиск локального установщика"

    $installer = Get-ChildItem -LiteralPath $WorkingDirectory -Filter $Mask -File -ErrorAction SilentlyContinue |
        Sort-Object LastWriteTime -Descending |
        Select-Object -First 1

    if ($installer) {
        Write-Log -Level "OK" -Message ("Найден {0}" -f $installer.Name)
        return $installer.FullName
    }

    Write-Log -Level "INFO" -Message "Локальный установщик не найден"
    return $null
}

function Download-LatestInstaller {
    param(
        [Parameter(Mandatory = $true)]
        [string]$DestinationDirectory
    )

    if (-not $DownloadLatest) {
        Write-Log -Level "ERROR" -Message "Скачивание отключено в конфигурации"
        throw "Local installer was not found and downloading is disabled."
    }

    Write-Log -Level "INFO" -Message "Скачивание последнего релиза с GitHub"

    $apiUrl = "https://api.github.com/repos/rustdesk/rustdesk/releases/latest"
    $headers = @{
        "User-Agent" = "RustDesk-KZVS-Deployment"
    }

    $release = Invoke-RestMethod -Uri $apiUrl -Headers $headers
    $asset = $release.assets |
        Where-Object { $_.name -like "*x86_64.exe" } |
        Select-Object -First 1

    if (-not $asset) {
        Write-Log -Level "ERROR" -Message "В релизе GitHub не найден файл *x86_64.exe"
        throw "GitHub release does not contain an x86_64 installer."
    }

    $destinationPath = Join-Path -Path $DestinationDirectory -ChildPath $asset.name

    Write-Log -Level "INFO" -Message ("URL установщика: {0}" -f $asset.browser_download_url)
    Write-Log -Level "INFO" -Message ("Путь сохранения: {0}" -f $destinationPath)

    Invoke-WebRequest -Uri $asset.browser_download_url -Headers $headers -OutFile $destinationPath

    if (-not (Test-Path -LiteralPath $destinationPath)) {
        Write-Log -Level "ERROR" -Message "Не удалось сохранить установщик после загрузки"
        throw "Installer download failed."
    }

    Write-Log -Level "OK" -Message ("Установщик сохранён: {0}" -f $destinationPath)
    return $destinationPath
}

function Get-InstalledRustDeskPath {
    $candidatePaths = @()

    if ($env:ProgramFiles) {
        $candidatePaths += (Join-Path -Path $env:ProgramFiles -ChildPath "RustDesk\rustdesk.exe")
    }

    if (${env:ProgramFiles(x86)}) {
        $candidatePaths += (Join-Path -Path ${env:ProgramFiles(x86)} -ChildPath "RustDesk\rustdesk.exe")
    }

    foreach ($candidatePath in $candidatePaths) {
        if ($candidatePath -and (Test-Path -LiteralPath $candidatePath)) {
            return $candidatePath
        }
    }

    return $null
}

function Get-RustDeskVersion {
