function Install-RustDesk {
    param(
        [Parameter(Mandatory = $true)]
        [string]$InstallerPath
    )

    Write-Log -Level "INFO" -Message "Выполняется установка"

    $arguments = @("--silent-install")
    $process = Start-Process -FilePath $InstallerPath -ArgumentList $arguments -PassThru
    $startedAt = Get-Date
    $minimumWaitSeconds = 20
    $maximumWaitSeconds = 120

    # RustDesk после --silent-install может оставить стартовый EXE работающим как клиент.
    # Поэтому ждём появления установленного файла, а не бесконечного завершения процесса.
    while ($true) {
        $elapsedSeconds = ((Get-Date) - $startedAt).TotalSeconds
        $installedPath = Get-InstalledRustDeskPath

        $process.Refresh()
        if ($process.HasExited -and $process.ExitCode -ne 0) {
            Write-Log -Level "ERROR" -Message ("Установщик завершился с кодом {0}" -f $process.ExitCode)
            throw "RustDesk installer failed with exit code $($process.ExitCode)."
        }

        if ($installedPath -and $elapsedSeconds -ge $minimumWaitSeconds) {
            if (-not $process.HasExited) {
                Write-Log -Level "INFO" -Message "Установщик остаётся запущенным, но установленный клиент уже найден"
            }

            break
        }

        if ($elapsedSeconds -ge $maximumWaitSeconds) {
            Write-Log -Level "ERROR" -Message ("Установка не завершилась за {0} секунд" -f $maximumWaitSeconds)
            throw "RustDesk executable was not found before the installation timeout."
        }

        Start-Sleep -Seconds 2
    }

    Write-Log -Level "OK" -Message "Установка завершена"
}

function Set-RustDeskOption {
    param(
        [Parameter(Mandatory = $true)]
        [string]$RustDeskPath,

        [Parameter(Mandatory = $true)]
        [string[]]$Arguments
