    # GUI-приложение не на всех сборках PowerShell 5.1 создаёт $LASTEXITCODE автоматически.
    $global:LASTEXITCODE = 0
    $output = & $RustDeskPath @Arguments 2>&1
    $exitCode = $global:LASTEXITCODE

    if ($exitCode -ne 0) {
        throw ("Команда RustDesk {0} завершилась с кодом {1}" -f $Arguments[0], $exitCode)
