function Get-RustDeskId {
    param(
        [Parameter(Mandatory = $true)]
        [string]$RustDeskPath
    )

    Write-Log -Level "INFO" -Message "Получение идентификатора RustDesk"
    $startedAt = Get-Date

    if ($IdInitialDelaySeconds -gt 0) {
        Write-Log -Level "INFO" -Message ("Ожидание запуска RustDesk перед получением ID: {0} секунд" -f $IdInitialDelaySeconds)
        Start-Sleep -Seconds $IdInitialDelaySeconds
    }

    $retryDelaySeconds = 2
    $waitingWasLogged = $false

    # После запуска службы ID появляется не мгновенно, поэтому ожидаем его готовности.
    while ($true) {
        $global:LASTEXITCODE = 0
        # Для GUI-сборки RustDesk в Windows PowerShell вывод надёжнее читается через Out-String.
        $idOutput = (& $RustDeskPath --get-id 2>$null | Out-String).Trim()
        $exitCode = $global:LASTEXITCODE
        $clientId = ($idOutput -split "`r?`n") |
            ForEach-Object { $_.Trim() } |
            Where-Object { $_ } |
            Select-Object -First 1

        if ($exitCode -eq 0 -and $clientId) {
            break
        }

        $elapsedSeconds = ((Get-Date) - $startedAt).TotalSeconds
        if ($elapsedSeconds -ge $IdTimeoutSeconds) {
            Write-Log -Level "ERROR" -Message ("Не удалось получить идентификатор RustDesk за {0} секунд" -f $IdTimeoutSeconds)
            throw "RustDesk ID was not received before the timeout."
        }

        if (-not $waitingWasLogged) {
            Write-Log -Level "INFO" -Message ("Идентификатор ещё не готов, ожидание до {0} секунд" -f $IdTimeoutSeconds)
            $waitingWasLogged = $true
        }

        Start-Sleep -Seconds $retryDelaySeconds
    }

    Write-Log -Level "OK" -Message "Получен идентификатор"
    Write-Host $clientId
    Add-Content -LiteralPath $script:LogFile -Value $clientId -Encoding UTF8

    return $clientId
}

