    $rustDeskPath = Get-InstalledRustDeskPath
    if (-not $rustDeskPath) {
        Write-Log -Level "ERROR" -Message "Файл rustdesk.exe не найден после установки"
        throw "RustDesk executable not found after installation."
    }

    Write-Log -Level "OK" -Message ("Найден клиент: {0}" -f $rustDeskPath)

    $newVersion = Get-RustDeskVersion -RustDeskPath $rustDeskPath
    Ensure-RustDeskService -RustDeskPath $rustDeskPath
    Configure-RustDesk -RustDeskPath $rustDeskPath
    Restart-RustDeskService
    $clientId = Get-RustDeskId -RustDeskPath $rustDeskPath
    Invoke-RustDeskUpdate -RustDeskPath $rustDeskPath

    if ($oldVersion) {
        Add-Content -LiteralPath $script:LogFile -Value ("OLD={0}" -f $oldVersion) -Encoding UTF8
    }

    if ($newVersion) {
        Add-Content -LiteralPath $script:LogFile -Value ("NEW={0}" -f $newVersion) -Encoding UTF8
    }

    Add-Content -LiteralPath $script:LogFile -Value ("ID={0}" -f $clientId) -Encoding UTF8

    Write-Host ""
    Write-Host "========================================"
    Write-Host "DONE"
    Write-Host ""
    Write-Host "Version:"
    if ($newVersion) {
        Write-Host $newVersion
    }
    else {
        Write-Host "Unknown"
    }
    Write-Host ""
    Write-Host "ID:"
    Write-Host $clientId
    Write-Host ""
    Write-Host "Server:"
    Write-Host $Server
    Write-Host ""
    Write-Host "Log:"
    Write-Host $script:LogFile
    Write-Host "========================================"
}
catch {
    $failureMessage = $_.Exception.Message

    try {
        Write-Log -Level "ERROR" -Message $failureMessage
    }
    catch {
        Write-Host ("[ERROR] {0}" -f $failureMessage) -ForegroundColor Red
    }

    Wait-ForInteractiveError
    exit 1
}

