$pathsToExclude = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
$processesToExclude = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
$extensionsToExclude = @('1CD', 'DT', 'CF')

$ibasesFilePath = Join-Path -Path $env:APPDATA -ChildPath '1C\1CEStart\ibases.v8i'
if (Test-Path -LiteralPath $ibasesFilePath) {
    $connectLines = Get-Content -LiteralPath $ibasesFilePath | Where-Object { $_ -match '^Connect=File=' }

    foreach ($line in $connectLines) {
        if ($line -match '^Connect=File="?([^"]+)"?$') {
            $databasePath = $matches[1].Trim()
            if ($databasePath) {
                [void]$pathsToExclude.Add($databasePath)
            }
        }
    }
}

$standardPaths = @(
    'C:\База Розница',
    (Join-Path -Path $env:APPDATA -ChildPath '1C'),
    (Join-Path -Path $env:LOCALAPPDATA -ChildPath '1C'),
    (Join-Path -Path $env:PROGRAMFILES -ChildPath '1cv8'),
    (Join-Path -Path ${env:PROGRAMFILES(x86)} -ChildPath '1cv8'),
    (Join-Path -Path $env:APPDATA -ChildPath '1C\1cv8\ExtCompT')
)

foreach ($path in $standardPaths) {
    if ($path) {
        [void]$pathsToExclude.Add($path)
    }
