$platformRoots = @(
    (Join-Path -Path $env:PROGRAMFILES -ChildPath '1cv8'),
    (Join-Path -Path ${env:PROGRAMFILES(x86)} -ChildPath '1cv8')
)

$processNames = @(
    '1cv8.exe',
    '1cv8c.exe',
    '1cv8s.exe',
    'ragent.exe',
    'rmngr.exe',
    'rphost.exe',
    'dbgs.exe'
)

foreach ($platformRoot in $platformRoots) {
    if (-not $platformRoot -or -not (Test-Path -LiteralPath $platformRoot)) {
        continue
    }

    $versionFolders = Get-ChildItem -LiteralPath $platformRoot -Directory -ErrorAction SilentlyContinue
    foreach ($versionFolder in $versionFolders) {
        $binPath = Join-Path -Path $versionFolder.FullName -ChildPath 'bin'
        if (-not (Test-Path -LiteralPath $binPath)) {
            continue
        }

        foreach ($processName in $processNames) {
            $processPath = Join-Path -Path $binPath -ChildPath $processName
            if (Test-Path -LiteralPath $processPath) {
                [void]$processesToExclude.Add($processPath)
            }
        }
    }
}

foreach ($path in $pathsToExclude) {
    Add-DefenderExclusionPath -Path $path
}

foreach ($extension in $extensionsToExclude) {
    Write-Host "Adding exclusion extension: .$extension"
    Add-MpPreference -ExclusionExtension $extension
}

foreach ($processPath in $processesToExclude) {
    Add-DefenderExclusionProcess -Path $processPath
